import{_ as t,o as s,c as a,ak as i}from"./chunks/framework.sV-XtlWr.js";const u=JSON.parse('{"title":"Test selections","description":"Run only the tests that matter: saved and built-in selections, balanced shards, impact from a diff, and the CI guard that keeps a selection honest.","frontmatter":{"title":"Test selections","description":"Run only the tests that matter: saved and built-in selections, balanced shards, impact from a diff, and the CI guard that keeps a selection honest.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/test-selection.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/test-selection.html"}],["meta",{"property":"og:title","content":"Test selections | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Run only the tests that matter: saved and built-in selections, balanced shards, impact from a diff, and the CI guard that keeps a selection honest."}]]},"headers":[],"relativePath":"features/test-selection.md","filePath":"features/test-selection.md","lastUpdated":1790921321000}'),n={name:"features/test-selection.md"};function o(r,e,h,d,l,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="test-selections" tabindex="-1">Test selections <a class="header-anchor" href="#test-selections" aria-label="Permalink to &quot;Test selections&quot;">​</a></h1><p>A <strong>selection</strong> is a named subset of your suite that Piwi resolves from the run history it already keeps, then hands back as a command you can run. Instead of a <code>@smoke</code> tag convention and a grep pattern in a CI file that drift apart, you describe the subset once (&quot;critical tests, under 15 s each, not quarantined&quot;) and <code>piwi run</code> turns it into the tests to run. A selection is resolved on demand, never frozen, so a renamed file or a newly flaky test is reflected the next time you resolve it.</p><h2 id="run-one" tabindex="-1">Run one <a class="header-anchor" href="#run-one" aria-label="Permalink to &quot;Run one&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke</span></span></code></pre></div><p><code>piwi run &lt;key&gt;</code> resolves the selection and runs <code>playwright test</code> with exactly those tests. It finds your dashboard the way the reporter does, through <code>PIWI_DASHBOARD_URL</code>, <code>PIWI_API_KEY</code> (if auth is on) and <code>PIWI_PROJECT_NAME</code>, and passes anything after <code>--</code> straight to Playwright. The run is <strong>stamped</strong> with the selection it came from, so the <a href="/features/pr-feedback.html">pull-request comment</a> names the subset, and a <a href="/guide/ci.html">gate</a> can re-resolve the same definition to check nothing was silently dropped.</p><p>If the dashboard is unreachable, <code>piwi run</code> falls back to the full suite with a warning (and reuses the last good resolution from <code>.piwi/selection-cache.json</code> when it has one): a reporting problem never breaks the test run. Pass <code>--strict</code> to invert that for CI, where an unresolvable selection should stop the pipeline. Resolving a named selection to <strong>zero</strong> tests is always an error: a smoke job that silently runs nothing is worse than one that fails loudly.</p><h3 id="print-shard-and-reorder" tabindex="-1">Print, shard and reorder <a class="header-anchor" href="#print-shard-and-reorder" aria-label="Permalink to &quot;Print, shard and reorder&quot;">​</a></h3><p><code>piwi select &lt;key&gt;</code> resolves and prints the Playwright arguments instead of running them, for a two-step job. Three flags shape a resolution:</p><ul><li><code>--shard i/n</code> keeps only shard <em>i</em> of <em>n</em> (up to 1,000 shards), split so each shard&#39;s summed test duration is even. The split is <strong>lock-aware</strong>: every test that shares a <a href="/reference/test-metadata.html#test-locks">lock</a> goes to the same shard, because Playwright serializes lock holders only inside one process. Shard with <code>piwi run --shard</code> rather than Playwright&#39;s own <code>--shard</code>, which would split the lock; a resolution whose tests share a lock carries a <code>split-lock</code> warning.</li><li><code>--fail-fast</code> puts the least-reliable tests first, so a likely failure surfaces early. It reorders and never drops, so a <code>--require-selection</code> gate still sees the whole set.</li><li><code>--budget 5m</code> caps the total time for this resolution.</li></ul><p><code>piwi run --shard</code> jobs merge into one run that still covers the whole selection. Every flag and the output formats are in the <a href="/reference/cli.html#select-run">CLI reference</a>.</p><h2 id="built-in-selections" tabindex="-1">Built-in selections <a class="header-anchor" href="#built-in-selections" aria-label="Permalink to &quot;Built-in selections&quot;">​</a></h2><p>Two selections exist for every project with no setup:</p><table tabindex="0"><thead><tr><th>Key</th><th>What it resolves to</th></tr></thead><tbody><tr><td><code>failed</code></td><td>Tests whose most recent execution failed or timed out.</td></tr><tr><td><code>quarantine-free</code></td><td>The whole suite minus tests under an active <a href="/features/flaky-tests.html">quarantine</a>.</td></tr></tbody></table><h2 id="defining-a-selection" tabindex="-1">Defining a selection <a class="header-anchor" href="#defining-a-selection" aria-label="Permalink to &quot;Defining a selection&quot;">​</a></h2><p>Save a selection through the dashboard or the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API</a>. The <code>definition</code> is declarative JSON: OR-ed <code>include</code> groups, minus OR-ed <code>exclude</code> groups, then pins, a budget and a limit — applied in that order.</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;include&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;tags&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;smoke&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;priority&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;critical&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;high&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;maxAvgDurationMs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;exclude&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;quarantined&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;budget&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;maxTotalDurationMs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rankBy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;failureLikelihood&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Within a group every predicate must hold (AND); a test matches <code>include</code> if it matches any group (OR). An empty or absent <code>include</code> starts from the whole suite. The predicates, all optional:</p><table tabindex="0"><thead><tr><th>Predicate</th><th>Matches when</th></tr></thead><tbody><tr><td><code>ids</code></td><td>the test-case id is one of these</td></tr><tr><td><code>tags</code> / <code>anyTags</code></td><td>the test carries all / any of these tags</td></tr><tr><td><code>owner</code>, <code>priority</code>, <code>feature</code></td><td>the <code>piwi:</code> annotation is one of these</td></tr><tr><td><code>files</code></td><td>the file path matches one of these globs (<code>**</code>, <code>*</code>, <code>?</code>)</td></tr><tr><td><code>suitePath</code>, <code>text</code></td><td>the describe chain / title (or file) contains this substring</td></tr><tr><td><code>quarantined</code>, <code>flaky</code>, <code>neverRun</code></td><td>the test is (or is not) in that state</td></tr><tr><td><code>minPassRate</code> / <code>maxPassRate</code></td><td>pass rate over executed runs is within bounds (0–1)</td></tr><tr><td><code>minAvgDurationMs</code> / <code>maxAvgDurationMs</code></td><td>average duration is within bounds</td></tr><tr><td><code>lastStatus</code></td><td>the latest execution&#39;s status is one of these</td></tr><tr><td><code>failedInLastRuns</code></td><td>the test failed within its last <em>N</em> executions (N ≤ 25)</td></tr></tbody></table><p>An unknown predicate is a validation error, not a silent no-op — a typo fails loudly rather than resolving to a wider set than you meant.</p><h3 id="budgets-and-pins" tabindex="-1">Budgets and pins <a class="header-anchor" href="#budgets-and-pins" aria-label="Permalink to &quot;Budgets and pins&quot;">​</a></h3><p><code>budget</code> turns a selection into a knapsack: tests are ranked (<code>failureLikelihood</code>, <code>recentFailure</code>, <code>priority</code>, <code>slowest</code> or <code>fastest</code>) and taken until their summed average duration hits <code>maxTotalDurationMs</code>. &quot;The best five minutes of this suite&quot; is an empty <code>include</code> plus a budget. <code>pins</code> force individual tests in (<code>add</code>) or out (<code>remove</code>) by test- case id, on top of whatever the predicates matched. <code>limit</code> caps the count last.</p><h2 id="from-a-playwright-config" tabindex="-1">From a Playwright config <a class="header-anchor" href="#from-a-playwright-config" aria-label="Permalink to &quot;From a Playwright config&quot;">​</a></h2><p>To run <code>PIWI_SELECTION=smoke playwright test</code> instead of <code>piwi run</code>, resolve the selection in an ESM config (it needs top-level <code>await</code>):</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { defineConfig } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@playwright/test&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { wrapConfig, resolveSelection } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> selection</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> resolveSelection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// reads PIWI_SELECTION; undefined when unset</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wrapConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">defineConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ grep: selection?.grep </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> RegExp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(selection.grep) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> undefined</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }));</span></span></code></pre></div><p>It stamps the run like <code>piwi run</code>, and returns <code>undefined</code> (so everything runs) when no selection is named or the dashboard cannot be reached.</p><h2 id="guard-it-in-ci" tabindex="-1">Guard it in CI <a class="header-anchor" href="#guard-it-in-ci" aria-label="Permalink to &quot;Guard it in CI&quot;">​</a></h2><p><code>piwi gate --require-selection &lt;key&gt;</code> catches a smoke job that silently shrank: the dashboard re-resolves the selection&#39;s current definition and fails the build if any test it now matches did not run, or ran and failed.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # run the subset, stamping the run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --require-selection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # then assert it held</span></span></code></pre></div><p>It composes with the other <a href="/guide/ci.html">gate</a> rules (<code>--max-new-regressions</code>, <code>--fail-on-flaky</code>, …). A quarantined test is exempt: quarantine already means &quot;don&#39;t gate on this test&quot;.</p><h2 id="in-the-dashboard-and-for-agents" tabindex="-1">In the dashboard, and for agents <a class="header-anchor" href="#in-the-dashboard-and-for-agents" aria-label="Permalink to &quot;In the dashboard, and for agents&quot;">​</a></h2><p>The project&#39;s <strong>Selections</strong> tab lists the built-ins and your saved selections, with a builder that previews what a definition resolves to (the matching tests, the estimated duration, any warnings and the exact command) before you save it. Agents use the selection tools of the <a href="/reference/mcp-tools.html#workflow">MCP server</a> and the <code>run-the-right-tests</code> skill.</p><h2 id="health-and-drift" tabindex="-1">Health and drift <a class="header-anchor" href="#health-and-drift" aria-label="Permalink to &quot;Health and drift&quot;">​</a></h2><p>A selection resolves fresh every time, so the set it runs can change under you: a renamed file drops out of a <code>files</code> glob, a test turns flaky and falls below a <code>minPassRate</code>, and the job stays green while covering less. The Selections tab shows a <strong>drifted</strong> badge when what a selection resolves to now differs from what its last <code>piwi run</code> recorded (the run stamped the hash and count it resolved then), and counts the quarantined tests it carries.</p><p>Above the list, a <strong>coverage</strong> line counts the tests that <em>no</em> stored selection matches: nothing routine runs them as a named subset. Built-in selections don&#39;t count toward coverage (<code>quarantine-free</code> matches almost everything). Agents get the same data from <code>analyze_selections</code>.</p><h2 id="impact-from-diff" tabindex="-1">Impact-from-diff <a class="header-anchor" href="#impact-from-diff" aria-label="Permalink to &quot;Impact-from-diff&quot;">​</a></h2><p><code>piwi run impact --base &lt;ref&gt;</code> runs only the tests your change affects. The reporter computes the working-tree diff against <code>&lt;ref&gt;</code> locally (<code>git diff --name-only</code>), and the dashboard maps those files to tests through observed edges:</p><ul><li><strong>Direct</strong>: a changed file that <em>is</em> a test file maps to the tests defined in it.</li><li><strong>Reach</strong>: a changed support file (a page object, helper, or app module) maps to the tests whose most recent execution ran through it, per their captured source frames.</li><li><strong>Code reach</strong>: a changed application file maps to the tests that executed it (<a href="/features/code-reach.html">code reach</a>).</li></ul><p>It fails safe: an unmapped <em>source</em> file widens the run to the full suite with a warning. A docs-only change runs nothing.</p><h2 id="suggestions" tabindex="-1">Suggestions <a class="header-anchor" href="#suggestions" aria-label="Permalink to &quot;Suggestions&quot;">​</a></h2><p>Piwi can <em>propose</em> selections and tags from the history it keeps, with the evidence attached, never applied. The <strong>Suggestions</strong> panel on the Selections tab (and the <code>suggest_selections</code> MCP tool) surface three kinds:</p><ul><li><strong><code>@slow</code> tags</strong>: tests whose average duration is above the suite&#39;s 95th percentile.</li><li><strong><code>@feature</code> tags</strong>: the dominant route family a test hits (say <code>checkout</code>) when it carries no <code>feature</code> annotation.</li><li><strong>A mined smoke suite</strong>: a greedy set cover over <em>observed</em> route coverage under a time budget, keeping the test that adds the most new routes until the budget is spent. Only stable tests qualify. &quot;Save as selection&quot; turns the picks into a selection pinned to exactly those tests.</li></ul><p>Coverage here means the routes a test was <em>seen</em> to hit on recent runs, not instrumented code coverage.</p><h2 id="what-selections-are-not" tabindex="-1">What selections are not <a class="header-anchor" href="#what-selections-are-not" aria-label="Permalink to &quot;What selections are not&quot;">​</a></h2><ul><li><strong>Not instrumented test-impact analysis.</strong> Predicates read <em>observed</em> history (durations, pass rates, statuses), not a build-time dependency graph.</li><li><strong>Not a way to hide failures.</strong> <a href="/features/flaky-tests.html">Quarantine</a> decides a test&#39;s verdict; a selection only decides whether it runs. The full suite stays your reference; selections are for the fast loops in between.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/reference/cli.html#select-run">Piwi CLI</a>: every flag of <code>select</code> and <code>run</code></li><li><a href="/guide/ci.html">CI &amp; sharding</a>: the gate in a CI job</li><li><a href="/features/analytics.html#test-filter">Analytics</a>: filter every number by a selection</li><li><a href="/features/flaky-tests.html">Flaky tests &amp; quarantine</a>: what decides a test&#39;s verdict</li></ul>`,46)])])}const k=t(n,[["render",o]]);export{u as __pageData,k as default};
